import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';  // ✅ Redirect if not logged in
import { Container, Row, Col, Card, Spinner, Alert } from 'react-bootstrap';

const MyEvents = () => {
  const [myEvents, setMyEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const navigate = useNavigate();  // ✅ Hook for redirection

  useEffect(() => {
    const fetchMyEvents = async () => {
      const accessToken = localStorage.getItem('accessToken');
      if (!accessToken) {
        console.log("❌ No token found");
        return;
      }
    
      const response = await fetch('/api/events/myevents', {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${accessToken}`,  // Ensure the correct token is sent
        },
      });
    
      const data = await response.json();
      if (response.ok) {
        console.log("🎉 Events fetched successfully", data);
      } else {
        console.error("❌ Error fetching my events:", data);
      }
    };
    
  }, []);
  

  return (
    <Container className="mt-5">
      <h2 className="text-center mb-4">My Registered Events</h2>

      {loading ? (
        <div className="text-center">
          <Spinner animation="border" variant="info" />
        </div>
      ) : error ? (
        <Alert variant="danger" className="text-center">{error}</Alert>
      ) : myEvents.length > 0 ? (
        <Row>
          {myEvents.map((event) => (
            <Col key={event._id} md={4} className="mb-4">
              <Card className="shadow">
                <Card.Body>
                  <Card.Title>{event.title}</Card.Title>
                  <Card.Text>{event.description}</Card.Text>
                  <Card.Text>📅 {new Date(event.date).toLocaleString()}</Card.Text>  
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <Alert variant="info" className="text-center">No registered events yet.</Alert>
      )}
    </Container>
  );
};

export default MyEvents;
